"""Pilot task suite: specs given to agents; hidden tests graded by the computer."""
TASKS = {
"slugify": ("easy", '''Write `slugify(s: str) -> str`: lowercase the text; every maximal run of characters that are not ASCII letters or digits becomes a single "-"; no leading or trailing "-". Examples: slugify("Hello, World!") == "hello-world"; slugify("  --A__b--  ") == "a-b"; slugify("Café 2026") == "caf-2026"; slugify("!!!") == "".'''),
"roman": ("medium", '''Write `roman_to_int(s: str) -> int` for standard Roman numerals from 1 to 3999 (I V X L C D M, subtractive pairs IV IX XL XC CD CM only). Raise ValueError for anything that is not the unique canonical form of a number in that range, e.g. "IIII", "VX", "IC", "MMMM", "", "iv", "XM", "VV", "IIV", "CMC".'''),
"intervals": ("easy", '''Write `merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]`: closed intervals (a, b) with a <= b, in any order; merge those that overlap or touch (share an endpoint, e.g. (1,3) and (3,5)); return them sorted by start. Integers that are merely adjacent, like (1,2) and (3,4), are NOT merged.'''),
"lru": ("medium", '''Write class `LRUCache(capacity: int)` with `get(key)` returning the value or -1 if absent, and `put(key, value)`. When putting a new key into a full cache, evict the least recently used key. Both get (when found) and put count as use. Putting an existing key updates its value and makes it most recent. Capacity 0 stores nothing.'''),
"expr": ("hard", '''Write `evaluate(s: str) -> fractions.Fraction` evaluating arithmetic over integers with exact rational results: + - * / ** and parentheses, unary minus and unary plus, whitespace anywhere. Precedence: ** highest and right-associative (2**3**2 == 512), then unary +/-, then * and /, then + and - (left-associative). Note -2**2 == -4 and 2**-1 == 1/2. Exponents are integers after evaluation; raise ValueError if an exponent is not an integer, on division by zero (ZeroDivisionError is also acceptable), or on any syntax error.'''),
"glob": ("hard", '''Write `glob_match(pattern: str, path: str) -> bool` for "/"-separated paths. "?" matches one character other than "/"; "*" matches any run (possibly empty) of characters other than "/"; a whole path segment "**" matches zero or more entire segments. Everything else matches itself. The empty path "" has no segments; "a//b" has an empty middle segment. Examples: glob_match("src/**/*.py", "src/a.py") is True; glob_match("src/**/*.py", "src/x/y/a.py") is True; glob_match("src/*.py", "src/x/a.py") is False; glob_match("**", "") is True; glob_match("a/**", "a") is True; glob_match("a?c", "a/c") is False.'''),
"topo": ("medium", '''Write `topo_sort(deps: dict[str, list[str]]) -> list[str]`: deps[n] lists the nodes n depends on (which must come before n). Nodes mentioned only as dependencies are included too. Return an order in which every node comes after its dependencies; whenever several nodes are ready, take the alphabetically smallest first. Raise ValueError if there is a cycle.'''),
"busdays": ("medium", '''Write `business_days(start: datetime.date, end: datetime.date, holidays: set[datetime.date]) -> int`: the number of days d with start <= d < end that are Monday to Friday and not in holidays. If end < start, return minus the count for the range [end, start). Must be fast for ranges of millions of days with few holidays.'''),
"canon": ("hard", '''Write `canonical_json(v) -> str` producing RFC 8785 (JCS) canonical JSON for values made of None, bool, int, str, list and dict with str keys: no whitespace; object members sorted by their keys compared as sequences of UTF-16 code units; strings escaped with \\" \\\\ \\b \\f \\n \\r \\t, other characters below U+0020 as \\u00xx with lowercase hex, every other character (including non-ASCII and "/") written as itself; ints in plain decimal; true/false/null.'''),
"bigmul": ("medium", '''Write `multiply(a: str, b: str) -> str` multiplying two integers given as decimal strings (optional leading "-", no leading zeros except "0" itself), returning the product in the same form ("0", never "-0"). Do not convert the whole strings with int(); work digit by digit. Inputs may have thousands of digits.'''),
"dijkstra": ("hard", '''Write `shortest_path(graph: dict[str, list[tuple[str, int]]], src: str, dst: str)` returning (cost, path) for the cheapest path from src to dst (non-negative integer weights; nodes may appear only as edge targets), where path is the list of nodes from src to dst. Among equally cheap paths return the one whose node list is lexicographically smallest (compare lists of strings). Return None if dst is unreachable. src == dst gives (0, [src]).'''),
"wrap": ("medium", '''Write `wrap(text: str, width: int) -> list[str]`: split text into paragraphs at runs of one or more blank lines (lines empty or only whitespace); within a paragraph, words are maximal runs of non-whitespace. Fill lines greedily with words separated by single spaces, each line at most width characters. A word longer than width always starts a new line and is cut into pieces of exactly width characters (the last piece possibly shorter), each piece on its own line; the next word starts a new line. Paragraphs are separated by one empty string "" in the output. Empty or all-whitespace text gives []. width >= 1.'''),
}
